package com.vibeguard.samples.linking; import jakarta.validation.Valid; import jakarta.validation.constraints.NotBlank; import java.util.*; import org.springframework.beans.factory.annotation.Value; import org.springframework.http.ResponseEntity; import org.springframework.web.bind.annotation.*; /** Restricts sensitive identity linking to the authenticated account owner. */ @RestController @RequestMapping("/api/accounts") public class AccountLinkController { private final List<Link> links=new ArrayList<>(); @Value("${ACCOUNT_LINKING_KEY:}") private String key; @Value("${ACCOUNT_LINKING_OWNER_ID:}") private String owner; @PostMapping("/{id}/links") public ResponseEntity<Link> link(@RequestHeader("X-Account-Linking-Key") String supplied,@PathVariable String id,@Valid @RequestBody Request request){if(!key.equals(supplied)||!owner.equals(id))return ResponseEntity.status(403).build();Link link=new Link(id,request.provider(),request.subject());links.add(link);return ResponseEntity.status(201).body(link);}record Request(@NotBlank String provider,@NotBlank String subject){}record Link(String accountId,String provider,String subject){} }
